<template><view class="page"><view class="segment"><view :class="mode==='overview'?'active':''" @click="mode='overview'">计划总览</view><view :class="mode==='stages'?'active':''" @click="mode='stages'">阶段计划</view></view><view v-if="error" class="card"><view class="error">{{error}}</view><button class="secondary" @click="load">重新加载</button></view><view v-else-if="loading" class="loading">正在加载…</view><EmptyState v-else-if="!plan"/>
<template v-else><view class="plan-hero"><image src="/static/dengkemiao.png" mode="aspectFit"/><view class="row"><text class="exam-name">{{plan.examName}}</text><picker :range="plans" range-key="examName" @change="change"><view class="switch">切换</view></picker></view><view class="hero-days">{{plan.remainingDays}}<text> 天</text></view><view class="hero-note">距离考试还有 · {{plan.examDate}}</view></view>
<template v-if="mode==='overview'"><view class="card"><view class="row"><text class="section">学习进度</text><text class="muted">已完成 {{plan.completedTasks}} / {{plan.totalTasks}} 项</text></view><view class="progress"><view class="fill" :style="{width:plan.progress+'%'}"/></view><view class="muted percent">{{plan.progress}}%</view><view class="quick-links"><view @click="tasks"><view class="quick-icon amber">▦</view>计划日历</view><view @click="tasks"><view class="quick-icon mint">▤</view>任务清单</view><view @click="mode='stages'"><view class="quick-icon blue">✓</view>阶段目标</view><view @click="record"><view class="quick-icon cyan">▥</view>学习记录</view></view></view><view class="card quote"><view><view class="section">今日一句</view><view class="muted">坚持不是因为看到了希望，<br/>而是因为坚持才有希望。</view></view><image src="/static/dengkemiao.png" mode="aspectFit"/></view><button class="primary" @click="tasks">开始今天的学习</button><view class="row bottom-links"><text class="link" @click="create">＋ 创建新计划</text><text class="link" @click="product">查看完整方案 ›</text></view></template>
<template v-else><view class="section">你的阶段路线</view><view v-for="(s,i) in plan.stages" :key="s.id" class="card stage"><view class="row"><view class="row"><view class="number">0{{i+1}}</view><text class="stage-name">{{s.name}}</text></view><text class="badge">{{s.progress}}%</text></view><view class="muted range">{{s.startDate}} — {{s.endDate}}</view><view>{{s.goal}}</view><view class="progress"><view class="fill" :style="{width:s.progress+'%'}"/></view></view><view class="notice">通用路线按你的科目和时间预算分配任务。具体知识点请结合考试大纲安排。</view></template></template></view></template>
<script setup>
import {ref} from 'vue';import {onShow} from '@dcloudio/uni-app';import {api,selected,select} from '../../api';import EmptyState from '../../components/EmptyState.vue'
const plans=ref([]),plan=ref(null),error=ref(''),loading=ref(true),mode=ref('overview')
async function load(){loading.value=true;error.value='';try{plans.value=await api.plans();const p=plans.value.find(p=>p.id===selected())||plans.value[0];plan.value=p?await api.plan(p.id):null;if(p)select(p.id)}catch(e){error.value=e.message}finally{loading.value=false}}
async function change(e){select(plans.value[Number(e.detail.value)].id);await load()}onShow(load)
function create(){uni.navigateTo({url:'/pages/exam/create'})}function tasks(){uni.switchTab({url:'/pages/task/index'})}function product(){uni.navigateTo({url:'/pages/payment/index'})}function record(){uni.navigateTo({url:'/pages/record/index'})}
</script>
<style scoped>
.segment{display:flex;background:#EAF0F8;border-radius:40rpx;padding:4rpx;margin:6rpx auto 24rpx;width:85%;font-size:25rpx;text-align:center;color:#7B8DA6}.segment view{flex:1;padding:12rpx;border-radius:40rpx}.segment .active{background:#1677FF;color:#fff;font-weight:650;box-shadow:0 4rpx 12rpx #1677FF25}.plan-hero{position:relative;overflow:hidden;background:linear-gradient(135deg,#6CB1FF,#096CFF);border-radius:24rpx;padding:30rpx;color:white;margin-bottom:24rpx}.plan-hero image{position:absolute;right:0;bottom:-30rpx;width:260rpx;height:260rpx}.exam-name{font-size:33rpx;font-weight:750;max-width:80%;position:relative;z-index:1}.switch{background:#fff;color:#1677FF;border-radius:30rpx;font-size:22rpx;padding:5rpx 24rpx;position:relative;z-index:2}.hero-days{font-size:96rpx;line-height:1.4;font-weight:800;position:relative;z-index:1}.hero-days text{font-size:28rpx;font-weight:400}.hero-note{font-size:22rpx;color:#DDEEFF;position:relative}.card .section{font-size:27rpx;margin:0}.percent{text-align:right;margin-top:6rpx}.quick-links{display:flex;justify-content:space-between;margin-top:24rpx;text-align:center;font-size:21rpx}.quick-icon{width:64rpx;height:64rpx;border-radius:16rpx;line-height:64rpx;font-size:32rpx;color:white;margin:0 auto 12rpx}.amber{background:linear-gradient(135deg,#FFDA84,#FFA825)}.mint{background:linear-gradient(135deg,#85E4C5,#20C59B)}.blue{background:linear-gradient(135deg,#8DC9FF,#2F8AFF)}.cyan{background:linear-gradient(135deg,#7DE0EA,#29B4C9)}.quote{display:flex;justify-content:space-between;background:linear-gradient(120deg,#F4FAFF,#EAF4FF);padding:28rpx}.quote image{width:150rpx;height:150rpx}.quote .section{margin-bottom:16rpx}.quote .muted{font-size:23rpx;line-height:1.9}.stage-name{font-size:30rpx;font-weight:700}.number{width:64rpx;height:64rpx;background:#EAF4FF;color:#1677FF;border-radius:18rpx;line-height:64rpx;text-align:center;font-weight:800}.range{margin:20rpx 0 12rpx}.bottom-links{margin-top:24rpx}
</style>
